  ('740b2c2e-ee39-57b7-9674-c5578b6447d9', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'assignments', 'E-1..E-4', null, 'Private, Specialist/Corporal — Broadening training opportunities', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'CompTIA Certifications, Certified Electronics Technician (CET), ETA Fiber Optics and Data Cabling Certifications, Basic Electricity and Electronics-Digital (BEE-D) Certifications, RADAR Electronics Technician (RAD), US Military Apprenticeship Program (USMAP), Culture and Language Training. Soldiers should strive to master the skills necessary to obtain certifications listed by MOS on the Army COOL website.', 'cbfdf70cbeb1f4038880a3001ecd3bc960783f0fc5db96c321b908f8dba4a029', 10, 10, '10', 87, null, null, false, null),
