  ('89f71007-4a03-5b26-801c-56378393b2bd', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'development', 'E-6', null, 'Staff Sergeant — Institutional assignments', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'Instructor, Training Developer, Operations Sergeant.', '4a54b4060a4f95065d11aa725b18e598d009edd5f55cc6631cd8c56b124ff150', 11, 11, '11', 101, null, null, false, null),
  ('dc197735-a397-5bc3-9f8f-51b716583e9a', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94A', null, 'assignments', 'E-6', null, 'Staff Sergeant — Critical leader development', 'Chapter 4. Military Occupational Specialty 94A Land Combat Electronics Missile', 'SSG’s are required to complete 24 months of rated time in the one of the following positions to build the requisite KSB’s to be successful in the next grade. Land Combat Electronic Missile System Foreman, Section Sergeant, Team Chief.', '144d7c417f8f55a6e3366bd1883033920cde7d5ea87d7f70ee9c1c03423b49d5', 11, 11, '11', 102, null, null, false, null),
