  ('1fd7720c-fd3c-5b32-9519-150a1432bc31', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94F', null, 'assignments', 'E-6', null, 'Staff Sergeant — Critical leader development', 'Chapter 13. Military Occupational Specialty 94F Computer /Detection Systems Repairer', 'SSG’s are required to complete 24 months of rated time in the one of the following positions in order to build the requisite KSB’s to be successful in the next grade. Computer/ Detection System Repair Supervisor, Shop Foreman, Section Sergeant, Team Chief.', '4cc3e2cdec0e7c79b642e61f96820961f5fb47d41276bafe242d2a5ec96a976c', 18, 18, '18', 195, null, null, false, null),
