  ('d0caad6b-cf95-5ebb-975c-54cfd26bddb1', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94H', null, 'assignments', 'E-6', null, 'Staff Sergeant — Critical leader development', 'Chapter 16. Military Occupational Specialty 94H Test, Measurement, and Diagnostic Equipment Maintenance Support Specialist', 'SSG’s are required to complete 24 months of rated time in the one of the following positions in order to build the requisite KSB’s to be successful in the next grade. TMDE QA/QC TI, Team Chief, Shop Foreman, Section Sergeant.', '21fdb0440c15b41a65ac9e713408185fa453bdf18088179f5959122ec9d6b045', 20, 20, '20', 223, null, null, false, null),
