  ('0299a578-c31a-541d-bfe0-e98a89a1ebf7', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94R', null, 'assignments', 'E-6', null, 'Staff Sergeant — Critical leader development', 'Chapter 25. Military Occupational Specialty 94R Avionic and Survivability Equipment', 'SSG’s are required to complete 24 months of rated time in the one of the following positions in order to build the requisite KSB’s to be successful in the next grade. Avionics Systems Repair Supervisor, Shop Foreman, Team Chief, Section Sergeant.', '1c4fbaab074e806c0a25d76b1556b860a1f975e5c264cf1dfb9492180cd736e1', 26, 26, '26', 310, null, null, false, null),
