  ('7babb849-dca2-506f-8969-f16dc92a1502', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94T', null, 'assignments', 'E-6', null, 'Staff Sergeant — Critical leader development', 'Chapter 31. Military Occupational Specialty 94T Avenger System Repairer', 'SSG’s are required to complete 24 months of rated time in the one of the following positions to build the requisite KSB’s to be successful in the next grade. Section Chief, Shop Foreman, Team Chief, Section Sergeant.', 'a8e4dc719678829daf3f345b27d7eb0092ed4b926c9ce5c0f1c91d73a3ec5f9e', 30, 30, '30', 375, null, null, false, null),
