  ('c7ca5555-f51a-5f3b-a41f-567badf06da0', 'd69ea188-6dea-5cf5-b1a1-3780e1f5a088', 'Army', 'enlisted', '94Y', null, 'assignments', 'E-6', null, 'Staff Sergeant — Critical leader development', 'Chapter 37. Military Occupational Specialty 94Y Automated Test Systems', 'SSG’s are required to complete 24 months of rated time in the one of the following positions in order to build the requisite KSB’s to be successful in the next grade. Shop Foreman, Team Chief, Section Sergeant.', '65e52b74a90a5230f6e8f084a499a31bbfc952a676048b17e1a9b18080162519', 34, 34, '34', 414, null, null, false, null),
